  const platS=`<rect class="a-enc" x="${ENC.x}" y="${ENC.y}" width="${ENC.w}" height="${ENC.h}" rx="26"/><text class="a-zlabel" x="40" y="58">CI / GitOps · externe ▸</text><text class="a-zlabel" x="1092" y="118">▾ déploie dans le cluster</text><text class="a-zlabel" x="392" y="806">Télémétrie de tous les services ▾</text><text class="a-zlabel" x="388" y="332">Sécurité · PKI ▸</text><text class="a-zlabel" x="372" y="856">Observabilité &amp; Ops · in-cluster ▸</text>${pW}${pF}<g class="a-dotlayer">${pD}</g>${hetzCard}${pN}`;
