      [[40,60,'CI / GitOps · externe ▸'],[1092,118,'▾ déploie dans le cluster'],[392,806,'Télémétrie de tous les services ▾'],[388,332,'Sécurité · PKI ▸'],[372,856,'Observabilité & Ops · in-cluster ▸']].forEach(l=>pLabS+=`<text x="${l[0]}" y="${l[1]}" font-size="11" font-weight="800" letter-spacing="1.5" fill="${T.zl}">${esc(l[2])}</text>`);
