const EPIC_NODES={1:['MOB','KR','AUTH','API','PG','COL','IOT','MAIL'],2:['COL','IOT','ING','KAFKA','TS','PG'],3:['MOB','KR','API','ING','TS','COL','IOT'],4:['MOB','KR','API','ING','TS','COL','IOT','MAPS'],5:['CE','ING','TS','API','KR','MOB','COL','IOT','FCM'],6:['MOB','KR','CE','RAG','VEC','RR','AZ','API','AUD','TC'],7:['VET','KR','API','AUTH','PG','KAFKA','TS','CE','AUD','S3'],8:['MOB','KR','API','PG','STRIPE','BACK'],9:['MOB','KR','AUTH','API','PG','AUD','CE','S3'],10:['MOB','KR','CE','TC','KAFKA','API','AUD','VET'],11:['GHA','HELM','ARGO','K8S','SOPS','OTEL','PROM','LOKI','TEMPO','GRAF','STEPCA','IOT','COL','REG','INGRESS']};
// US sub-journey = epic edges filtered to endpoints in US node set
function usJourney(id,epicNum){const set=new Set(US_NODES[id]||EPIC_NODES[epicNum]||[]);const ej=EPIC_EDGES[epicNum]||[];const sub=ej.filter(s=>set.has(s.f)&&set.has(s.t));return sub.length?sub:ej;}

// ---- panels ----
let lastPanel=null;
function openPanel(id){document.querySelectorAll('.panel').forEach(p=>p.classList.remove('open'));document.getElementById(id).classList.add('open');document.getElementById('pscrim').classList.add('show');document.getElementById('reopen').classList.remove('show');lastPanel=id;syncTabs(id);}
function closePanels(){document.querySelectorAll('.panel').forEach(p=>p.classList.remove('open'));document.getElementById('pscrim').classList.remove('show');syncTabs(null);}
function syncTabs(id){document.querySelectorAll('.topbar .tb[data-panel]').forEach(b=>b.classList.toggle('on',b.dataset.panel===id));}
document.querySelectorAll('.topbar .tb[data-panel]').forEach(b=>b.onclick=()=>{b.dataset.panel===currentOpen()?closePanels():openPanel(b.dataset.panel);});
function currentOpen(){const o=document.querySelector('.panel.open');return o?o.id:null;}
document.querySelectorAll('.panel [data-close]').forEach(x=>x.onclick=closePanels);
document.getElementById('pscrim').onclick=closePanels;
document.getElementById('reopen').onclick=()=>{if(lastPanel)openPanel(lastPanel);};
const PLAT_NODES_SET=new Set(['K8S','HELM','ARGO','GHA','SOPS','STEPCA','OTEL','PROM','LOKI','TEMPO','GRAF','HETZ','REG','INGRESS']);
const isPlatJourney=j=>j.some(s=>PLAT_NODES_SET.has(s.f)||PLAT_NODES_SET.has(s.t));
function setPlatView(on){if(document.body.classList.contains('plat')!==on)document.getElementById('tPlat').click();}
function playJourney(j,label){closePanels();setPlatView(isPlatJourney(j));PAW.fit();PAW.play(j,label);document.getElementById('reopen').classList.add('show');}

